  + duration : int
  + publisher : string
}

class VHSFilm {
}

class DVDFilm {
}

class Author {
  + name : string
}

class Actor {
  + name : string
}

class Request {
}

Library "1" -- "*" User : has
Library "1" -- "*" BorrowableItem : has
Library "1" -- "*" Request : receives

User "0..1" -- "0..3" BorrowableItem : borrows

BorrowableItem <|-- Book
BorrowableItem <|-- MagazineIssue
BorrowableItem <|-- MusicCD
BorrowableItem <|-- Film
BorrowableItem <|-- VHSFilm
BorrowableItem <|-- DVDFilm

Book "*" -- "1..*" Author : written by
Film "*" -- "1..*" Actor : features

Request "0..*" -- "1" BorrowableItem : for
Request "0..*" -- "1" Library : sent to

@enduml

